import csv, json, statistics, math
from datetime import datetime
from collections import defaultdict, Counter
from pathlib import Path

fp='/app/benchmark/data.csv'

def parse_dt(s):
    return datetime.fromisoformat(s.replace('Z','+00:00'))

def quantile(sorted_vals, q):
    n=len(sorted_vals)
    if n==0: return float('nan')
    if n==1: return float(sorted_vals[0])
    pos=(n-1)*q
    lo=math.floor(pos); hi=math.ceil(pos)
    if lo==hi: return float(sorted_vals[lo])
    return float(sorted_vals[lo] + (sorted_vals[hi]-sorted_vals[lo])*(pos-lo))

def summary(vals):
    s=sorted(vals); n=len(s)
    mean=sum(s)/n if n else float('nan')
    med=quantile(s,0.5); q1=quantile(s,0.25); q3=quantile(s,0.75)
    var=(sum((x-mean)**2 for x in s)/(n-1)) if n>1 else 0.0
    return {'count':n,'mean':mean,'median':med,'min':min(s) if n else float('nan'),'max':max(s) if n else float('nan'),'std':math.sqrt(var),'q1':q1,'q3':q3,'iqr':q3-q1,'spread':(max(s)-min(s)) if n else float('nan')}

missing=Counter(); prices=defaultdict(list); lags=defaultdict(list)
coverage_sets=defaultdict(set); station_fuel_set=defaultdict(set)
all_nodes=set(); all_fuels=set(); recorded_min=None; recorded_max=None; rows=0

with open(fp, newline='', encoding='utf-8') as f:
    r=csv.DictReader(f)
    for row in r:
        rows+=1
        for k,v in row.items():
            if v is None or v=='': missing[k]+=1
        node=row['node_id']; fuel=row['fuel_type']
        all_nodes.add(node); all_fuels.add(fuel)
        station_fuel_set[node].add(fuel); coverage_sets[fuel].add(node)
        prices[fuel].append(float(row['price_pence']))
        rec=parse_dt(row['recorded_at']); src=parse_dt(row['source_updated_at'])
        lags[fuel].append((rec-src).total_seconds()/3600.0)
        if recorded_min is None or rec<recorded_min: recorded_min=rec
        if recorded_max is None or rec>recorded_max: recorded_max=rec

price_stats={k:summary(v) for k,v in prices.items()}
lag_stats={k:summary(v) for k,v in lags.items()}
all_lags=[x for vs in lags.values() for x in vs]; s_lags=sorted(all_lags)
stale=lambda t:100.0*sum(1 for x in all_lags if x>t)/len(all_lags)
station_fuel_dist=Counter(len(v) for v in station_fuel_set.values())
coverage={k:len(v) for k,v in coverage_sets.items()}

out={'overview':{'total_records':rows,'unique_stations':len(all_nodes),'fuel_types':sorted(all_fuels),'date_min':recorded_min.isoformat(),'date_max':recorded_max.isoformat(),'missing':dict(missing)},'price_stats':price_stats,'lag_stats':lag_stats,'station_fuels_dist':dict(sorted(station_fuel_dist.items())),'coverage':dict(sorted(coverage.items(), key=lambda kv: kv[1], reverse=True)),'overall_lag_median':quantile(s_lags,0.5),'overall_lag_mean':sum(all_lags)/len(all_lags),'stale_pct':{'gt24h':stale(24),'gt48h':stale(48),'gt72h':stale(72)}}
Path('/app/output').mkdir(exist_ok=True)
Path('/app/output/metrics.json').write_text(json.dumps(out, indent=2))
print(json.dumps({'rows':rows,'stations':len(all_nodes),'fuels':sorted(all_fuels),'lag_median_h':out['overall_lag_median'],'stale_gt24':out['stale_pct']['gt24h']}, indent=2))
